from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students")
    for s in students:
        if not s.email:
            raise ProjectError(
                f"no email for {s.display_name}"
            )


def _join(row: tuple, widths: List[int]) -> str:
    cells = zip(row, widths)
    return "  ".join(c.ljust(w) for c, w in cells).rstrip()


# ---
def contact_rows(students: List[Student]) -> List[str]:
    _check(students)
    rows = sorted(
        (s.display_name, s.section, s.email)
        for s in students
    )
    widths = [max(map(len, col)) for col in zip(*rows)]
    return [_join(row, widths) for row in rows]

