# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


def make(last, section="A", email="x@school.test"):
    return Student("1", last, "Pat", section, email)


class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_and_aligned(self):
        people = [make("Zed", "B"), make("Ames")]
        rows = contact_rows(people)
        self.assertEqual(rows, [
            "Ames, Pat  A  x@school.test",
            "Zed, Pat   B  x@school.test"
        ])

    def test_missing_email_names_student(self):
        with self.assertRaises(ProjectError) as ctx:
            contact_rows([make("Ames", email=None)])
        self.assertIn("Ames, Pat", str(ctx.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
